-- Lot 207 : payloads 181 a 210 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-067","moteur":"chatgpt","payload":"[RaccourcIA — /glassmorph]\n\nMISSION\nRéinterpréter un produit en verre translucide. Préserve la silhouette, produis épaisseur du verre, réfraction et reflets cohérents. Signale le concept de matière s’il peut être confondu avec le produit commercial réel.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel positionnement doit guider la mise en scène : accessible, premium, technique ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Produit en verre » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Préserve la silhouette, produis épaisseur du verre, réfraction et reflets cohérents. Signale le concept de matière s’il peut être confondu avec le produit commercial réel. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la forme, les proportions, le packaging, le logo fourni, les couleurs, matériaux et détails distinctifs du produit.\n\nÉVITER\nÉvite produit déformé, faux packaging, étiquette illisible, reflets incohérents, matière plastique générique et ombre flottante. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"e6d82cfe397a26ee36b2af1f8e6a2f03cf41c8edf5402b1d8ef1f80b605c11b0"},{"ref":"RCI-IMG-067","moteur":"claude","payload":"[RaccourcIA — /glassmorph]\n\nMISSION\nRéinterpréter un produit en verre translucide. Préserve la silhouette, produis épaisseur du verre, réfraction et reflets cohérents. Signale le concept de matière s’il peut être confondu avec le produit commercial réel.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel positionnement doit guider la mise en scène : accessible, premium, technique ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Produit en verre » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Préserve la silhouette, produis épaisseur du verre, réfraction et reflets cohérents. Signale le concept de matière s’il peut être confondu avec le produit commercial réel. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve la forme, les proportions, le packaging, le logo fourni, les couleurs, matériaux et détails distinctifs du produit.\n\nÉVITER\nÉvite produit déformé, faux packaging, étiquette illisible, reflets incohérents, matière plastique générique et ombre flottante. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"810fb19f8fc265f28575a0228ffd263c88141c556be2580eeac763a6f065248a"},{"ref":"RCI-IMG-067","moteur":"gemini","payload":"[RaccourcIA — /glassmorph]\n\nMISSION\nRéinterpréter un produit en verre translucide. Préserve la silhouette, produis épaisseur du verre, réfraction et reflets cohérents. Signale le concept de matière s’il peut être confondu avec le produit commercial réel.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel positionnement doit guider la mise en scène : accessible, premium, technique ou cho